CREATE OR ALTER procedure [dbo].[GetDynamicAssets] @assetTypeId int, @userId int, @filter nvarchar(250), @apiNamesInOutput bit = 0, @listableFieldsOnly bit = 1, @pagingEnabled bit = 1, @pageNumber int = 0, @pageSize int = 10, @sortField nvarchar(250), @sortDirection nvarchar(10), @filters [dbo].[AssetFiltersTable] readonly as begin set nocount on;
/*Filter Types: A: Attribute F: Single-value field I: Field ON a relationship (inferred) M: Multi-value field O: Responsibility P: Parent relationship R: Relationship */ if @sortField = '' begin set @sortField = null end
if @filter = '' begin set @filter = null end
set @pageNumber = @pageNumber * @pageSize
declare @admin bit select @admin = IsAdministrator from reporting.Global_Resource where ResourceID = @userId
declare @parentIntersectTypeId int = null select @parentIntersectTypeId = I.ID from IntersectType I inner join AssetType O on O.ID = @assetTypeId and O.Object = I.Object and O.ObjectID = I.ObjectID inner join [Predicate] P on P.ID = I.PredicateID and P.[Type] = case when O.Class in (2,6) then 4 else 3 end
drop table if exists #ft;
select * into #ft from FieldType where AssetTypeID = @assetTypeId and [Type] not in ('File', 'Hidden', 'Password', 'FusionLookup', 'Attribute', 'FilteredLookup', 'ComplexRelationLookup', 'DataTableSelect', 'OwnershipLookup', 'RefListRelationship') order by ColumnOrder, [FriendlyName];
alter table #ft add DataType varchar(25) alter table #ft add ColumnName varchar(250) alter table #ft add ColumnStatement varchar(2500) alter table #ft add OrderStatement varchar(2500) alter table #ft add JoinStatement nvarchar(max) alter table #ft add FilterStatement varchar(2500) alter table #ft add TxtId varchar(25)
update #ft set TxtId = cast(ID as nvarchar), DataType = case [Type] when 'Boolean' then 'bit' when 'Decimal' then 'float' when 'DateTime' then 'datetime' when 'Date' then 'date' when 'Number' then 'bigint' else 'nvarchar' end, ColumnName = case when @apiNamesInOutput = 1 then REPLACE(REPLACE(Name, ' ', ''), '''', '') else 'Field' + cast(ID as nvarchar) end;
update T set T.JoinStatement = ' inner join FieldType FT'+TxtId+' with(nolock) on FT'+TxtId+'.ID = '+TxtId+' inner join FieldType FT'+TxtId+'R on FT'+TxtId+'R.ID = FT'+TxtId+'.LookupObjectFieldTypeID' + ' cross apply openjson(FT'+TxtId+'R.Definition) with (FieldTypeID int ''$.FieldTypeID'', DataType varchar(50) ''$.DataType'', [Path] varchar(250) ''$.Path'') FT'+TxtId+'RD' + ' left join [Intersect] FT'+TxtId+'_REL with(nolock) on FT'+TxtId+'.LookupObjectType = ''IntersectType'' and FT'+TxtId+'_REL.IntersectTypeID = FT'+TxtId+'.LookupObjectID' + ' and ( (FT'+TxtId+'_REL.Subject = A.Object and FT'+TxtId+'_REL.SubjectID = A.ObjectID) or (FT'+TxtId+'_REL.Object = A.Object and FT'+TxtId+'_REL.ObjectID = A.ObjectID) )' + ' left join Field F'+TxtId+'R with(nolock) on F'+TxtId+'R.ObjectType = case ' + ' when FT'+TxtId+'_REL.Subject = A.Object and FT'+TxtId+'_REL.SubjectID = A.ObjectID then FT'+TxtId+'_REL.Object ' + ' else FT'+TxtId+'_REL.Subject end' + ' and F'+TxtId+'R.ObjectID = case' + ' when FT'+TxtId+'_REL.Subject = A.Object and FT'+TxtId+'_REL.SubjectID = A.ObjectID then FT'+TxtId+'_REL.ObjectID' + ' else FT'+TxtId+'_REL.SubjectID end' + ' and F'+TxtId+'R.FieldTypeID = FT'+TxtId+'RD.FieldTypeID' + ' left join FieldJsonProperty F'+TxtId+'RP with(nolock) on F'+TxtId+'RP.FieldID = F'+TxtId+'R.ID and F'+TxtId+'RP.[Path] = FT'+TxtId+'RD.[Path]', T.ColumnStatement = 'F'+TxtId+'RP.Value', T.OrderStatement = case when T.DataType = 'nvarchar' then 'F'+TxtId+'RP.Value' else 'try_cast(F'+TxtId+'RP.Value as '+DataType+')' end, T.FilterStatement = case when @filter is not null and T.IsListable = 1 then '(F'+TxtId+'RP.Value like @filter)' when T.ID in (select TypeID from @filters where FilterType = 'F') then 'F'+TxtId+'RP.Value like (select top 1 FilterValues from @filters where TypeID = FT'+TxtId+'.ID)' else '' end from #ft T inner join FieldType S on S.ID = T.LookupObjectFieldTypeID and S.[Type] = 'JsonElement' where T.[Type] = 'FieldFromRelationship';
update T set T.JoinStatement = ' inner join FieldType FT'+TxtId+' with(nolock) on FT'+TxtId+'.ID = '+TxtId + ' left join [Intersect] FT'+TxtId+'_REL with(nolock) on FT'+TxtId+'.LookupObjectType = ''IntersectType'' and FT'+TxtId+'_REL.IntersectTypeID = FT'+TxtId+'.LookupObjectID and' + ' ( (FT'+TxtId+'_REL.Subject = A.Object and FT'+TxtId+'_REL.SubjectID = A.ObjectID) or (FT'+TxtId+'_REL.Object = A.Object and FT'+TxtId+'_REL.ObjectID = A.ObjectID) )' + ' left join Field F'+TxtId+'R with(nolock) on F'+TxtId+'R.ObjectType = case' + ' when FT'+TxtId+'_REL.Subject = A.Object and FT'+TxtId+'_REL.SubjectID = A.ObjectID then FT'+TxtId+'_REL.Object' + ' else FT'+TxtId+'_REL.Subject end' + ' and F'+TxtId+'R.ObjectID = case' + ' when FT'+TxtId+'_REL.Subject = A.Object and FT'+TxtId+'_REL.SubjectID = A.ObjectID then FT'+TxtId+'_REL.ObjectID' + ' else FT'+TxtId+'_REL.SubjectID end' + ' and F'+TxtId+'R.FieldTypeID = FT'+TxtId+'.LookupObjectFieldTypeID', T.ColumnStatement = 'F'+TxtId+'R.FormattedValue', T.OrderStatement = case when T.DataType = 'nvarchar' then 'F'+TxtId+'R.FormattedValue' else 'try_cast(F'+TxtId+'R.FormattedValue as '+DataType+')' end, T.FilterStatement = case when @filter is not null and T.IsListable = 1 then '(F'+TxtId+'R.FormattedValue like @filter)' when T.ID in (select TypeID from @filters where FilterType = 'F') then '( F'+TxtId+'R.FormattedValue like (select top 1 FilterValues from @filters where TypeID = FT'+TxtId+'.ID) )' else '' end from #ft T inner join FieldType S on S.ID = T.LookupObjectFieldTypeID and S.[Type] <> 'JsonElement' where T.[Type] = 'FieldFromRelationship';
update T set T.JoinStatement = ' inner join FieldType FT'+TxtId+' with(nolock) on FT'+TxtId+'.ID = '+TxtId + ' cross apply openjson(FT'+TxtId+'.Definition) with (FieldTypeID int ''$.FieldTypeID'', DataType varchar(50) ''$.DataType'', [Path] varchar(250) ''$.Path'') FT'+TxtId+'D' + ' left join Field F'+TxtId+' with(nolock) on F'+TxtId+'.FieldTypeID = '+cast(D.FieldTypeID as nvarchar)+' and F'+TxtId+'.AssetID = A.ID' + ' left join FieldJsonProperty F'+TxtId+'P with(nolock) on F'+TxtId+'P.FieldID = F'+TxtId+'.ID and F'+TxtId+'P.[Path] = FT'+TxtId+'D.[Path]', T.ColumnStatement = 'F'+TxtId+'P.Value', T.OrderStatement = case when D.DataType = 'nvarchar' then 'F'+TxtId+'P.Value' else 'try_cast(F'+TxtId+'P.Value as '+D.DataType+')' end, T.FilterStatement = case when @filter is not null and T.IsListable = 1 then '(F'+TxtId+'P.Value like @filter)' when T.ID in (select TypeID from @filters where FilterType = 'F') then 'F'+TxtId+'P.Value like (select top 1 FilterValues from @filters where TypeID = FT'+TxtId+'.ID)' else '' end from #ft T cross apply openjson(T.[Definition]) with (FieldTypeID int '$.FieldTypeID', DataType varchar(50) '$.DataType', [Path] varchar(250) '$.Path') D where T.[Type] = 'JsonElement';
declare @relationIsSubject bit = 0; declare @relationIsObject bit = 0; declare @relationSidesAreSame bit = 0;
if(exists (select 1 from #ft where IsListable = @listableFieldsOnly and [Type] = 'Relationship')) begin print 'Artifact list page contains relationship field types checking if all are of one side' select @relationIsSubject = cast (count(1) as bit) from [intersecttype] it inner join #ft ft on it.id = ft.lookupobjectid where ft.IsListable = @listableFieldsOnly and ft.[type] = 'relationship' and it.object = ft.[object] and it.objectid = ft.objectid and it.subject != ft.[object] and it.subjectid != ft.objectid and it.object != it.[subject] and it.objectid != it.subjectid
select @relationIsObject = cast (count(1) as bit) from [intersecttype] it inner join #ft ft on it.id = ft.lookupobjectid where ft.IsListable = @listableFieldsOnly and ft.[type] = 'relationship' and it.object != ft.[object] and it.objectid != ft.objectid and it.subject = ft.[object] and it.subjectid = ft.objectid and it.object != it.[subject] and it.objectid != it.subjectid
select @relationSidesAreSame = cast (count(1) as bit) from [intersecttype] it inner join #ft ft on it.id = ft.lookupobjectid where ft.IsListable = @listableFieldsOnly and ft.[type] = 'relationship' and it.object = ft.[object] and it.objectid = ft.objectid and it.subject = ft.[object] and it.subjectid = ft.objectid
print '- relationship field type target is subject is (1 true, 0 false) :' + cast(@relationIsSubject as varchar) print '- relationship field type target is object is (1 true, 0 false) :' + cast(@relationIsObject as varchar) print '- relationship field type target has same asset type both sides is (1 true, 0 false) :' + cast(@relationSidesAreSame as varchar) end
if (@relationIsSubject = 1 and @relationIsObject = 0 and @relationSidesAreSame = 0) begin update #ft set JoinStatement = ' left join FieldType FT'+TxtId+' with(nolock) on FT'+TxtId+'.ID = '+TxtId+' and FT'+TxtId+'.LookupObjectType = ''IntersectType''' + case when @listableFieldsOnly = 0 or IsListable = 1 then ' left join [Intersect] F'+TxtId+'R with(nolock) on F'+TxtId+'R.IntersectTypeID = FT'+TxtId+'.LookupObjectID and ( F'+TxtId+'R.Object = A.Object and F'+TxtId+'R.ObjectID = A.ObjectID )' + ' outer apply dbo.GetRelationshipDisplayValue(F'+TxtId+'R.Subject,F'+TxtId+'R.SubjectID ) as F'+TxtId else '' end, ColumnStatement = 'F'+TxtId+'.DisplayValue', OrderStatement = 'F'+TxtId+'.DisplayValue', FilterStatement = case when (@filter is not null and IsListable = 1) then '(F'+TxtId+'.DisplayValue like @filter)' when @listableFieldsOnly = 0 and ID in (select TypeID from @filters where FilterType = 'F') then 'F'+TxtId+'.DisplayValue like (select top 1 FilterValues from @filters where TypeID = FT'+TxtId+'.ID)' when @listableFieldsOnly = 1 and ID in (select TypeID from @filters where FilterType = 'F') then ' exists (' + ' select F'+TxtId+'N.DisplayValue ' + ' from [Intersect] F'+TxtId+'R with(nolock) ' + ' cross apply dbo.GetRelationshipDisplayValue(F'+TxtId+'R.Subject,F'+TxtId+'R.SubjectID) as F'+TxtId+'N ' + ' where F'+TxtId+'R.IntersectTypeID = FT'+TxtId+'.LookupObjectID ' + ' and ( (F'+TxtId+'R.Subject = A.Object and F'+TxtId+'R.SubjectID = A.ObjectID) or (F'+TxtId+'R.Object = A.Object and F'+TxtId+'R.ObjectID = A.ObjectID) ) ' + ' and F'+TxtId+'N.DisplayValue like (select top 1 FilterValues from @filters where TypeID = FT'+TxtId+'.ID)' + ' ) ' else '' end where [Type] = 'Relationship'; end else if (@relationIsObject =1 and @relationIsSubject = 0 and @relationSidesAreSame = 0 ) begin update #ft set JoinStatement = ' left join FieldType FT'+TxtId+' with(nolock) on FT'+TxtId+'.ID = '+TxtId+' and FT'+TxtId+'.LookupObjectType = ''IntersectType''' + case when @listableFieldsOnly = 0 or IsListable = 1 then ' left join [Intersect] F'+TxtId+'R with(nolock) on F'+TxtId+'R.IntersectTypeID = FT'+TxtId+'.LookupObjectID and ( F'+TxtId+'R.Subject = A.Object and F'+TxtId+'R.SubjectID = A.ObjectID )' + ' outer apply dbo.GetRelationshipDisplayValue(F'+TxtId+'R.Object,F'+TxtId+'R.ObjectID ) as F'+TxtId else '' end, ColumnStatement = 'F'+TxtId+'.DisplayValue', OrderStatement = 'F'+TxtId+'.DisplayValue', FilterStatement = case when (@filter is not null and IsListable = 1) then '(F'+TxtId+'.DisplayValue like @filter)' when @listableFieldsOnly = 0 and ID in (select TypeID from @filters where FilterType = 'F') then 'F'+TxtId+'.DisplayValue like (select top 1 FilterValues from @filters where TypeID = FT'+TxtId+'.ID)' when @listableFieldsOnly = 1 and ID in (select TypeID from @filters where FilterType = 'F') then ' exists (' + ' select F'+TxtId+'N.DisplayValue ' + ' from [Intersect] F'+TxtId+'R with(nolock) ' + ' cross apply dbo.GetRelationshipDisplayValue(case when F'+TxtId+'R.Subject = A.Object and F'+TxtId+'R.SubjectID = A.ObjectID then F'+TxtId+'R.Object else F'+TxtId+'R.Subject end,case when F'+TxtId+'R.Subject = A.Object and F'+TxtId+'R.SubjectID = A.ObjectID then F'+TxtId+'R.ObjectID else F'+TxtId+'R.SubjectID end) as F'+TxtId+'N ' + ' where F'+TxtId+'R.IntersectTypeID = FT'+TxtId+'.LookupObjectID ' + ' and ( (F'+TxtId+'R.Subject = A.Object and F'+TxtId+'R.SubjectID = A.ObjectID) or (F'+TxtId+'R.Object = A.Object and F'+TxtId+'R.ObjectID = A.ObjectID) ) ' + ' and F'+TxtId+'N.DisplayValue like (select top 1 FilterValues from @filters where TypeID = FT'+TxtId+'.ID)' + ' ) ' else '' end where [Type] = 'Relationship'; end else begin update #ft set JoinStatement = ' left join FieldType FT'+TxtId+' with(nolock) on FT'+TxtId+'.ID = '+TxtId+' and FT'+TxtId+'.LookupObjectType = ''IntersectType''' + case when @listableFieldsOnly = 0 or IsListable = 1 then ' left join [Intersect] F'+TxtId+'R with(nolock) on F'+TxtId+'R.IntersectTypeID = FT'+TxtId+'.LookupObjectID and ( (F'+TxtId+'R.Subject = A.Object and F'+TxtId+'R.SubjectID = A.ObjectID) or (F'+TxtId+'R.Object = A.Object and F'+TxtId+'R.ObjectID = A.ObjectID) )' + ' outer apply dbo.GetRelationshipDisplayValue(case when F'+TxtId+'R.Subject = A.Object and F'+TxtId+'R.SubjectID = A.ObjectID then F'+TxtId+'R.Object else F'+TxtId+'R.Subject end,case when F'+TxtId+'R.Subject = A.Object and F'+TxtId+'R.SubjectID = A.ObjectID then F'+TxtId+'R.ObjectID else F'+TxtId+'R.SubjectID end) as F'+TxtId else '' end, ColumnStatement = 'F'+TxtId+'.DisplayValue', OrderStatement = 'F'+TxtId+'.DisplayValue', FilterStatement = case when (@filter is not null and IsListable = 1) then '(F'+TxtId+'.DisplayValue like @filter)' when @listableFieldsOnly = 0 and ID in (select TypeID from @filters where FilterType = 'F') then 'F'+TxtId+'.DisplayValue like (select top 1 FilterValues from @filters where TypeID = FT'+TxtId+'.ID)' when @listableFieldsOnly = 1 and ID in (select TypeID from @filters where FilterType = 'F') then ' exists (' + ' select F'+TxtId+'N.DisplayValue ' + ' from [Intersect] F'+TxtId+'R with(nolock) ' + ' cross apply dbo.GetRelationshipDisplayValue(case when F'+TxtId+'R.Subject = A.Object and F'+TxtId+'R.SubjectID = A.ObjectID then F'+TxtId+'R.Object else F'+TxtId+'R.Subject end,case when F'+TxtId+'R.Subject = A.Object and F'+TxtId+'R.SubjectID = A.ObjectID then F'+TxtId+'R.ObjectID else F'+TxtId+'R.SubjectID end) as F'+TxtId+'N ' + ' where F'+TxtId+'R.IntersectTypeID = FT'+TxtId+'.LookupObjectID ' + ' and ( (F'+TxtId+'R.Subject = A.Object and F'+TxtId+'R.SubjectID = A.ObjectID) or (F'+TxtId+'R.Object = A.Object and F'+TxtId+'R.ObjectID = A.ObjectID) ) ' + ' and F'+TxtId+'N.DisplayValue like (select top 1 FilterValues from @filters where TypeID = FT'+TxtId+'.ID)' + ' ) ' else '' end where [Type] = 'Relationship'; end
update #ft set JoinStatement = 'left join FieldDetail F'+TxtId+' on F'+TxtId+'.FieldTypeID = '+TxtId+' and F'+TxtId+'.AssetID = A.ID', ColumnStatement = 'F'+TxtId+'.FormattedValue', OrderStatement = case when DataType = 'nvarchar' then 'F'+TxtId+'.FormattedValue' else 'try_cast(F'+TxtId+'.FormattedValue as '+DataType+')' end, FilterStatement = case when (@filter is not null and IsListable = 1) then '(F'+TxtId+'.FormattedValue like @filter)' when ID in ( select TypeID from @filters where FilterType = 'M' and AllowMultipleValues = 1 ) then '( exists(select 1 from @filters FF cross apply openjson(FF.FilterValues) MF cross apply string_split(F'+TxtId+'.Value,'','') EF where FF.TypeID = F'+TxtId+'.FieldTypeID and MF.[value] = EF.[value]) ' + IIF(AllowAllValue = 1, ' OR F'+TxtId+'.Value = ''0'' )', ' )') when ID in ( select TypeID from @filters where FilterType = 'M' and AllowMultipleValues = 0 ) then '( exists(select 1 from @filters FF cross apply openjson(FF.FilterValues) MF where FF.TypeID = F'+TxtId+'.FieldTypeID and F'+TxtId+'.[FormattedValue] = MF.value) ' + IIF(AllowAllValue = 1, ' OR F'+TxtId+'.Value = ''0'' )', ' )')
when ID in ( select TypeID from @filters where FilterType = 'F' and [Type] = 'Lookup' and AllowMultipleValues = 1 and ISNUMERIC(REPLACE(FilterValues, '%', '')) = 1 ) then '( exists(select 1 from @filters FF cross apply string_split(F'+TxtId+'.Value,'','') MF where FF.TypeID = F'+TxtId+'.FieldTypeID and MF.[value] = REPLACE(FF.FilterValues, ''%'', '''')) ' + IIF(AllowAllValue = 1, ' OR F'+TxtId+'.Value = ''0'' )', ' )') when ID in ( select TypeID from @filters where FilterType = 'F' and [Type] = 'Lookup' and AllowMultipleValues = 0 and ISNUMERIC(REPLACE(FilterValues, '%', '')) = 1 ) then '( exists(select 1 from @filters where TypeID = F'+TxtId+'.FieldTypeID and F'+TxtId+'.Value = REPLACE(FilterValues, ''%'', '''')) ' + IIF(AllowAllValue = 1, ' OR F'+TxtId+'.Value = ''0'' )', ' )') when ID in ( select TypeID from @filters where FilterType = 'F' and AllowMultipleValues = 1 and ( [Type] <> 'Lookup' or ISNUMERIC(REPLACE(FilterValues, '%', '')) = 0 ) ) then '( exists(select 1 from @filters FF cross apply string_split(F'+TxtId+'.FormattedValue,'','') MF where FF.TypeID = F'+TxtId+'.FieldTypeID and MF.[value] like FF.FilterValues) ' + IIF(AllowAllValue = 1, ' OR F'+TxtId+'.Value = ''0'' )', ' )') when ID in ( select TypeID from @filters where FilterType = 'F' and AllowMultipleValues = 0 and ( [Type] <> 'Lookup' or ISNUMERIC(REPLACE(FilterValues, '%', '')) = 0 ) ) then '( exists(select 1 from @filters where TypeID = F'+TxtId+'.FieldTypeID and F'+TxtId+'.FormattedValue like FilterValues) ' + IIF(AllowAllValue = 1, ' OR F'+TxtId+'.Value = ''0'' )', ' )') else '' end where JoinStatement is null and [Type] not in ('FieldFromRelationship', 'JsonElement', 'Relationship','Tag');
update #ft set JoinStatement = 'cross apply (select t.Value, t.uid from Tag T inner join AssetTag AT on AT.AssetId = A.Id and AT.TagId = T.Id order by t.value for json path)F'+TxtId+'(FormattedValue)', ColumnStatement = 'F'+TxtId+'.FormattedValue', OrderStatement = 'F'+TxtId+'.FormattedValue', FilterStatement = case when (@filter is not null and IsListable = 1) then '(exists(select top 1 t.value from tag t inner join AssetTag AT on AT.AssetId = A.Id and AT.TagId = T.Id where t.value like @filter))' when ((select count(*) from @filters where TypeID= TxtId) > 0 ) then '(exists(select TypeID from @filters AFT' +' inner join Tag T on T.Value LIKE AFT.FilterValues' +' inner join AssetTag AT on AT.TagId = T.Id AND AT.AssetID = A.Id' +' where AFT.TypeID = '+TxtId +' group by TypeID ))' end where JoinStatement is null and [Type] = 'Tag'
declare @countSql nvarchar(max), @sql nvarchar(max), @orderSql nvarchar(max), @filterSql nvarchar(max) = '', @parentColumns nvarchar(500) = '', @parentJoin nvarchar(500) = '', @editRightsColumns nvarchar(2500) = '', @hasFilters bit = 0, @displayValueJoin nvarchar(500)='', @displayValueColumns nvarchar(500)=''
if @admin = 1 begin set @editRightsColumns = '1 as P_CanEdit, 1 as P_CanDelete, ' end else begin declare @permissionCount int select @permissionCount = count(1) from UserAssetPermissions(@userId,@assetTypeId) if @permissionCount > 0 begin set @editRightsColumns = ' case when exists (select 1 from UserAssetPermissions(@userId,A.AssetTypeID) u where u.PermissionsBitMask & 2 = 2 and (u.AssetID = A.ID or (u.AssetID = 0 and u.AssetTypeID = A.AssetTypeID)) ) then 1 else 0 end as P_CanEdit, case when exists (select 1 from UserAssetPermissions(@userId,A.AssetTypeID) u where u.PermissionsBitMask & 4 = 4 and (u.AssetID = A.ID or (u.AssetID = 0 and u.AssetTypeID = A.AssetTypeID)) ) then 1 else 0 end as P_CanDelete, ' end else begin set @editRightsColumns = '0 as P_CanEdit, 0 as P_CanDelete, ' end end;
if @sortField is not null begin declare @sort nvarchar(250) = null
if @sortField = 'Parent' and @parentIntersectTypeId is not null begin set @sort = 'parp.DisplayValue' end else begin select @sort = OrderStatement from #ft where ColumnName = @sortField if @sort = '' OR @sort is null begin set @sort = 'A.ID' end end
if @sort <> '' AND @sort is not null begin set @sortDirection = IIF(@sortDirection = 'desc', 'desc', 'asc') set @orderSql = REPLACE(@sort, '''', '''''') + ' ' + @sortDirection end end else begin select @orderSql = string_agg(OrderStatement, ', ') WITHIN GROUP (ORDER BY SortOrder, Name) from #ft where SortOrder not in (0,99) and (IsListable = 1 or coalesce(FilterStatement,'')<>'')
if @orderSql = '' or @orderSql is null begin set @displayValueJoin = ' inner join AssetDisplayValue ADISPLAY on ADISPLAY.AssetID = A.ID' set @displayValueColumns= 'ADISPLAY.DisplayValue as Display,' set @orderSql = ' ADISPLAY.DisplayValue asc' end end
if @parentIntersectTypeId is not null begin set @parentColumns = 'arp.ParentArtifactID as ParentID, parp.DisplayValue as Parent, '''' as ParentUrl, ' set @parentJoin = ' inner join [utility].[ArtifactAssetParent] arp on A.ID = arp.AssetID inner join AssetDisplayValue parp on parp.AssetID = arp.ParentAssetID' end
set @countSql = 'select count(1)' set @countSql = @countSql + ' from Asset A ' select @countSql = @countSql + string_agg(JoinStatement, ' ') from #ft where (coalesce(JoinStatement,'') <> '') and (IsListable = 1 OR coalesce(FilterStatement,'') <> '') set @countSql = @countSql + @parentJoin + @displayValueJoin set @countSql = @countSql + ' where A.AssetTypeID = @assetTypeId and A.State = 1'
if exists(select 1 from #ft where coalesce(FilterStatement,'') <> '') begin declare @contraction varchar(5) = iif(@filter is not null, ' or ', ' and ')
select @filterSql = string_agg(FilterStatement, @contraction) from #ft where coalesce(FilterStatement,'') <> ''
if @contraction = ' or ' and @parentIntersectTypeId is not null begin set @filterSql = @filterSql + ' or parp.DisplayValue like @filter' end
set @filterSql = ' and (' + @filterSql + ')' set @hasFilters = 1 end;
if exists(select 1 from @filters where FilterType = 'A') begin set @hasFilters = 1 set @filterSql = iif(@filterSql is not null, @filterSql, '') + ' and A.ObjectID in (select ObjectID from AttributeDetail A inner join @filters F on F.FilterType = ''A'' and F.TypeID = A.AttributeTypeID and A.FormattedValue like F.FilterValues)' end
if exists(select 1 from @filters where FilterType = 'P') and @parentIntersectTypeId is not null begin set @hasFilters = 1 set @filterSql = iif(@filterSql is not null, @filterSql, '') + ' and parp.DisplayValue like (select top 1 FilterValues from @filters where FilterType = ''P'')' end
if exists(select 1 from @filters where FilterType = 'O') begin set @hasFilters = 1 set @filterSql = iif(@filterSql is not null, @filterSql, '') + ' and A.ID in (select AssetID from ResponsibilityDetail RD inner join @filters F on F.FilterType = ''O'' cross apply openjson(F.FilterValues) with (SecurityAsset varchar(1) ''$.SecurityAsset'', SecurityAssetID int ''$.SecurityAssetID'', ResponsibilityTypeID int ''$.ResponsibilityTypeID'') O where RD.SecurityAsset = O.SecurityAsset and RD.SecurityAssetID = O.SecurityAssetID and RD.ResponsibilityTypeID = O.ResponsibilityTypeID )' end
if exists(select 1 from @filters where FilterType = 'R') begin set @hasFilters = 1 declare @relationFilters table (RowId int identity, [Operator] varchar(25) NULL, [TypeID] [int] NOT NULL, [OptionalIdentifier] varchar(50) NULL, [FilterValues] [nvarchar](max) NOT NULL) insert into @relationFilters select [Operator], [TypeID], [OptionalIdentifier], [FilterValues] from @filters where FilterType = 'R' declare @current int = 1, @max int, @operator varchar(25), @typeID nvarchar(30), @optionalIdentifier varchar(50), @filterValues nvarchar(max) select @max = max(RowId) from @relationFilters while @current <= @max begin select @operator = [Operator], @typeID = cast(TypeID as nvarchar), @optionalIdentifier = OptionalIdentifier, @filterValues = FilterValues from @relationFilters where RowId = @current
if @operator = 'OR' begin set @filterSql = iif(@filterSql is not null, @filterSql, '') + ' and A.ObjectID in ( select ObjectID from [Intersect] with(nolock) where IntersectTypeID = '+@typeID+' and Subject = ''' + @optionalIdentifier + ''' and SubjectID in (' + @filterValues + ') union select SubjectID from [Intersect] with(nolock) where IntersectTypeID = '+@typeID+' and Object = ''' + @optionalIdentifier + ''' and ObjectID in (' + @filterValues + ') )' end else begin declare @filterAndRelations table (FindID int, SqlStatement nvarchar(500)) insert into @filterAndRelations select value, 'and A.ObjectID in ( select ObjectID from [Intersect] with(nolock) where IntersectTypeID = '+@typeID+' and Subject = ''' + @optionalIdentifier + ''' and SubjectID = '+cast(value as nvarchar)+' union select SubjectID from [Intersect] with(nolock) where IntersectTypeID = '+@typeID+' and Object = ''' + @optionalIdentifier + ''' and ObjectID = '+cast(value as nvarchar)+' )' from string_split(@filterValues, ',') select @filterSql = iif(@filterSql is not null, @filterSql, '') + string_agg(SqlStatement, ' ') from @filterAndRelations end
set @current = @current + 1 end end
if exists(select 1 from @filters where FilterType = 'I') -- Field ON a relationship begin set @hasFilters = 1
declare @relationFieldFilters table (RowId int identity, [Operator] varchar(25) NULL, [TypeID] [int] NOT NULL, [OptionalIdentifier] varchar(50) NULL, [FilterValues] [nvarchar](max) NOT NULL)
insert into @relationFieldFilters select [Operator], [TypeID], [OptionalIdentifier], [FilterValues] from @filters where FilterType = 'I'
declare @iCurrent int = 1, @iMax int, @iOperator varchar(25), @iTypeID nvarchar(30), @iOptionalIdentifier varchar(50), @iFilterValues nvarchar(max) select @iMax = max(RowId) from @relationFieldFilters while @iCurrent <= @iMax begin select @iOperator = [Operator], @iTypeID = cast(TypeID as nvarchar), @iOptionalIdentifier = OptionalIdentifier, @iFilterValues = FilterValues from @relationFieldFilters where RowId = @iCurrent
set @filterSql = iif(@filterSql is not null, @filterSql, '') + ' and exists(select F.ID from Field F inner join FieldType FT on FT.ID = F.FieldTypeID and FT.ID = ' + @iTypeID + ' and F.FormattedValue like ''' + REPLACE(@iFilterValues, '''', '''''') + '''' + ' inner join [Intersect] I on F.ObjectType = ''Intersect'' and I.ID = F.ObjectID and ( (I.Subject = A.Object and I.SubjectID = A.ObjectID) or (I.Object = A.Object and I.ObjectID = A.ObjectID) ) )'
set @iCurrent = @iCurrent + 1 end end
declare @cantReadAssetTypeCount int = 0, @cantReadAssetTypeSql nvarchar(500) = '', @cantReadAssetCount int = 0, @cantReadAssetSql nvarchar(500) = ''
select @cantReadAssetTypeCount = count(1) from AssetTypesUserCantRead(@userId) where AssetTypeID = @assetTypeId select @cantReadAssetCount = count(1) from AssetsByTypeUserCantRead(@userId,@assetTypeId)
if @cantReadAssetTypeCount > 0 begin set @cantReadAssetTypeSql = ' and not exists (select 1 from AssetTypesUserCantRead(@userId) u where u.AssetTypeID = @assetTypeId)' end if @cantReadAssetCount > 0 begin set @cantReadAssetSql = ' and not exists (select 1 from AssetsByTypeUserCantRead(@userId,@assetTypeId) u where u.AssetID = A.ID)' end
if @hasFilters = 1 begin set @countSql = @countSql + @filterSql end set @countSql = @countSql + @cantReadAssetTypeSql + @cantReadAssetSql
set @sql = 'select A.AssetTypeID, A.ID, A.ObjectID, A.Uid, [dbo].[GenerateObjectUrl](A.Object, T.ObjectID, A.ObjectID) as Url, ' + @parentColumns + @displayValueColumns + @editRightsColumns select @sql = @sql + string_agg(ColumnStatement + ' as ' + ColumnName, ', ') from #ft where (coalesce(JoinStatement,'') <> '') and coalesce(ColumnStatement,'') <> '' and (IsListable = 1 or @listableFieldsOnly = 0)
set @sql = @sql + ' from Asset A inner join AssetType T on T.ID = A.AssetTypeID ' select @sql = @sql + string_agg(JoinStatement, ' ') from #ft where (coalesce(JoinStatement,'') <> '') and (IsListable = 1 OR @listableFieldsOnly = 0 OR coalesce(FilterStatement,'') <>'') set @sql = @sql + @parentJoin + @displayValueJoin set @sql = @sql + ' where A.AssetTypeID = @assetTypeId and A.State = 1'
if @hasFilters = 1 begin set @sql = @sql + @filterSql end
set @sql = @sql + @cantReadAssetTypeSql + @cantReadAssetSql set @sql = @sql + ' order by ' + @orderSql if @pagingEnabled = 1 begin set @sql = @sql + ' OFFSET(@pageNumber) ROWS FETCH NEXT (@pageSize) ROWS ONLY' end
declare @parameters nvarchar(max) set @parameters = '@assetTypeId int, @filter nvarchar(250), @userId int, @pageNumber int, @pageSize int, @filters [dbo].[AssetFiltersTable] readonly'
print 'count sql [' + @countSql + ']'
exec sp_executesql @countSql, @parameters, @assetTypeId = @assetTypeId, @filter = @filter, @userId = @userId, @pageNumber = @pageNumber, @pageSize = @pageSize, @filters = @filters
print 'sql [' + @sql + ']'
exec sp_executesql @sql, @parameters, @assetTypeId = @assetTypeId, @filter = @filter, @userId = @userId, @pageNumber = @pageNumber, @pageSize = @pageSize, @filters = @filters end

